def digits_to_number(digits: Sequence[int]) -> int:
    """ Return a positive integer that consists the same digits in the
    order they appear in digits.

    For example, if digits=[1, 2], digit_to_number returns 12.
    >>> digits_to_number([0])
    0
    """
    result = 0
    power = len(digits) - 1
    for d in digits:
        result += d * (10 ** power)
        power -= 1
    return result


def get_common_factors(num1: int, num2: int) -> Set[int]:
    """ Returns a set of common divisor numbers between `num1` and `num2`.

    >>> get_common_factors(20, 30)
    {2, 5}
    """
    set_1 = set()
    set_2 = set()
    for i in range(1, min(num1, num2) + 1):
        if num1 % i == 0:
            set_1.add(i)
        if num2 % i == 0:
            set_2.add(i)
    return set_1.intersection(set_2)


